// @ts-check
import { defineConfig } from 'astro/config';
import wix from '@wix/astro';
import react from '@astrojs/react';
import sitemap from '@astrojs/sitemap';
import wixHostingAdapter from '@wix/astro-wix-hosting-adapter';
import { dispPaths } from './src/data/disp.ts';
import { retiredPosts } from './src/data/retired-posts.ts';

// Wix-managed headless setup (as generated by `npm create @wix/new headless link`),
// wired by hand to keep the existing Headless Business site. Pages opt into
// prerendering; Wix hosting serves them at clean URLs.
export default defineConfig({
  site: 'https://www.integpro.com.au',
  output: 'server',
  adapter: wixHostingAdapter(),
  integrations: [
    wix(),
    react(),
    sitemap({
      customPages: dispPaths.map((p) => `https://www.integpro.com.au${p}`),
      // Match the canonical URLs in Base.astro, which drop the trailing slash (except on the home page).
      serialize: (item) => ({ ...item, url: item.url.replace(/([^/])\/$/, '$1') }),
    }),
  ],
  image: { domains: ['static.wixstatic.com'] },
  // Retired pages: keep old URLs working for visitors and search engines.
  redirects: {
    '/medical-iso': { status: 301, destination: '/iso-13485-medical-devices-quality-management-system' },
    '/iso-disp-services': { status: 301, destination: '/services' },
    // Sitemap addresses left over from the old Wix editor site.
    '/sitemap-integpro.xml': { status: 301, destination: '/sitemap-index.xml' },
    '/pages-sitemap.xml': { status: 301, destination: '/sitemap-index.xml' },
    ...Object.fromEntries(
      Object.entries(retiredPosts).map(([from, to]) => [`/post/${from}`, { status: 301, destination: `/post/${to}` }]),
    ),
  },
  security: { checkOrigin: false },
  devToolbar: { enabled: false },
});
